fn array_split(mut a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // We'll split the input vector into two parts at index k.
    // Choose k = floor(n/2). This guarantees:
    //  - k + (n - k) = n
    //  - when n > 1, both k < n and (n - k) < n
    let k = a.len() / 2;
    let second = a.split_off(k);
    // `a` now contains the first k elements, and `second` contains the rest.
    (a, second)
}

